import{_ as o,o as r,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Developer Summit - CephFS","description":"","frontmatter":{"title":"Ceph Developer Summit - CephFS","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["CephFS","分布式存储","Ceph 协议","存储集群","灾难恢复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_CephFS.md","filePath":"posts/2025/Ceph_Developer_Summit_-_CephFS.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Ceph_Developer_Summit_-_CephFS.md"};function a(s,e,n,u,h,c){return r(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="ceph-分布式存储会议纪要-cephfs-组件讨论" tabindex="-1"><strong>Ceph 分布式存储会议纪要 - CephFS 组件讨论</strong> <a class="header-anchor" href="#ceph-分布式存储会议纪要-cephfs-组件讨论" aria-label="Permalink to &quot;**Ceph 分布式存储会议纪要 - CephFS 组件讨论**&quot;">​</a></h3><p><strong>会议主题</strong>: CephFS 组件讨论（伞形发布） <strong>时间</strong>: [会议时间] <strong>参与人员</strong>: [与会人员列表]</p><h4 id="_1-mirror-daemon-cli-增强与健康状态报告" tabindex="-1"><strong>1. Mirror Daemon CLI 增强与健康状态报告</strong> <a class="header-anchor" href="#_1-mirror-daemon-cli-增强与健康状态报告" aria-label="Permalink to &quot;**1. Mirror Daemon CLI 增强与健康状态报告**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: <ul><li>当前 Mirror Daemon 的状态报告功能较为基础，缺乏管理员所需的详细信息。</li><li>计划通过 <code>service daemon</code> 接口将状态信息推送至 <code>ceph-mgr</code>，并支持通过 <code>ceph CLI</code> 查询。</li><li>讨论是否将 Mirror Daemon 的错误状态反映到集群健康状态。</li></ul></li><li><strong>决策</strong>: <ul><li>优先实现通过 <code>service daemon</code> 接口上报状态至 <code>ceph-mgr</code>。</li><li>需进一步讨论是否修改集群健康状态。</li></ul></li><li><strong>后续行动</strong>: <ul><li>Jos 和 Weni 负责推进 CLI 改进。</li><li>联系 Dashboard 团队讨论数据展示需求。</li></ul></li></ul><h4 id="_2-cephfs-灾难恢复工具的进度反馈" tabindex="-1"><strong>2. CephFS 灾难恢复工具的进度反馈</strong> <a class="header-anchor" href="#_2-cephfs-灾难恢复工具的进度反馈" aria-label="Permalink to &quot;**2. CephFS 灾难恢复工具的进度反馈**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: <ul><li>当前灾难恢复工具（如 <code>data-scan</code>）缺乏进度反馈，用户无法预估完成时间。</li><li>利用 <code>ceph-mgr</code> 的 <code>progress module</code> 上报进度，支持多工作线程独立统计。</li><li>若 <code>ceph-mgr</code> 不可用，直接输出进度至 <code>stdout/stderr</code>。</li></ul></li><li><strong>决策</strong>: <ul><li>采用 <code>progress module</code> 作为主要方案，<code>stdout</code> 回退为辅。</li><li>每个工作线程独立上报进度，不聚合统计。</li></ul></li><li><strong>后续行动</strong>: <ul><li>Ed 和 Mahesh 完善进度跟踪实现，优先提交 PR。</li></ul></li></ul><h4 id="_3-cephfs-subvolume-隔离-quarantine-功能" tabindex="-1"><strong>3. CephFS Subvolume 隔离（Quarantine）功能</strong> <a class="header-anchor" href="#_3-cephfs-subvolume-隔离-quarantine-功能" aria-label="Permalink to &quot;**3. CephFS Subvolume 隔离（Quarantine）功能**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: <ul><li>需求场景：应对勒索软件攻击，隔离特定 Subvolume 禁止读写。</li><li>技术挑战：协议修改、客户端处理、会话密钥吊销。</li></ul></li><li><strong>决策</strong>: <ul><li>优先修改 CAP 协议，支持返回隔离错误码。</li><li>旧客户端回退至 Blocklist 或挂起操作。</li></ul></li><li><strong>后续行动</strong>: <ul><li>Milind 和 Weni 设计协议变更方案，提交社区讨论。</li></ul></li></ul><h4 id="_4-subvolume-v3-状态更新" tabindex="-1"><strong>4. Subvolume V3 状态更新</strong> <a class="header-anchor" href="#_4-subvolume-v3-状态更新" aria-label="Permalink to &quot;**4. Subvolume V3 状态更新**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: <ul><li>目标：V3 为最终版 Subvolume 布局，修复 V1/V2 的设计缺陷。</li><li>升级计划：支持从 V1/V2 自动升级至 V3。</li></ul></li><li><strong>后续行动</strong>: <ul><li>Rishab 完善 PR 并推动 Review，目标纳入伞形发布。</li></ul></li></ul><h4 id="_5-其他议题" tabindex="-1"><strong>5. 其他议题</strong> <a class="header-anchor" href="#_5-其他议题" aria-label="Permalink to &quot;**5. 其他议题**&quot;">​</a></h4><ul><li><strong>Op Tracker 增强</strong>: Greg 计划改进 MDS Op Tracker，增加 Cap 更新的可视性，辅助调试卡死问题。</li><li><strong>终端 UI 工具提案</strong>: Eager 提议基于 C++ 库开发交互式 CLI 工具，提升用户体验。</li></ul><h3 id="行动计划总结" tabindex="-1"><strong>行动计划总结</strong> <a class="header-anchor" href="#行动计划总结" aria-label="Permalink to &quot;**行动计划总结**&quot;">​</a></h3><p>| <strong>负责人</strong> | <strong>任务</strong> | <strong>时间节点</strong> | ||-|--| | Jos/Weni | Mirror Daemon CLI 改进 | 下一个版本 | | Ed/Mahesh | 灾难恢复工具进度反馈 | PR 进行中 | | Milind | Subvolume Quarantine 协议设计 | 待定 | | Rishab | Subvolume V3 代码 Review | 伞形发布 | | Greg | MDS Op Tracker 改进 | 进行中 |</p><p><strong>备注</strong>: 未决事项需通过邮件列表进一步讨论。</p><p><strong>关键词保留</strong>:</p><ul><li>Mirror Daemon, CRUSH algorithm, RADOS, ceph-mgr, CAP protocol, Subvolume, Quarantine, Op Tracker,灾备恢复（disaster recovery）, cephfs-mirror.</li></ul>',17)])])}const g=o(t,[["render",a]]);export{p as __pageData,g as default};
